-- 导出  表 jd2508.lottery_codes 结构
DROP TABLE IF EXISTS `lottery_codes`;
CREATE TABLE IF NOT EXISTS `lottery_codes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lottery_code` varchar(10) DEFAULT NULL COMMENT '抽奖码（唯一，如 “AB1234”）',
  `prize_level` tinyint(2) DEFAULT NULL COMMENT '对应奖品等级（1 = 一等奖，2 = 二等奖...，0 = 谢谢参与）',
  `status` tinyint(2) NOT NULL DEFAULT '1' COMMENT '1有效，0表示禁用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `lottery_code` (`lottery_code`)
) ENGINE=InnoDB AUTO_INCREMENT=8001 DEFAULT CHARSET=utf8mb4 COMMENT='换奖码表';

