-- 导出  表 jd2508.lottery_drawrecords 结构
DROP TABLE IF EXISTS `lottery_drawrecords`;
CREATE TABLE IF NOT EXISTS `lottery_drawrecords` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `user_id` bigint(20) unsigned NOT NULL COMMENT '关联用户ID（外键，关联用户表user.id）',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号（关联订单表orders.order_no）',
  `lottery_code` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '开奖码（8位字母数字混编，小写，关联lottery_codes.lottery_code）',
  `prize_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '奖项名称，记录名称防止奖品修改',
  `lottery_prize_info` text COLLATE utf8mb4_unicode_ci COMMENT '奖品备注,备查',
  `prize_level` tinyint(1) NOT NULL DEFAULT '0' COMMENT '奖品等级1-8',
  `draw_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开奖时间（默认当前时间）',
  `is_won` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否中奖（1=中奖，0=未中奖）',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`) COMMENT '用户ID索引，用于查询用户开奖记录',
  KEY `idx_order_no` (`order_no`) COMMENT '订单号索引，用于关联订单查询',
  KEY `idx_lottery_code` (`lottery_code`) COMMENT '开奖码索引，用于关联开奖码表查询',
  KEY `idx_draw_time` (`draw_time`) COMMENT '开奖时间索引，用于按时间筛选记录'
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='开奖记录表（存储用户每次开奖的结果）';

