-- 导出  表 jd2508.lottery_prize 结构
DROP TABLE IF EXISTS `lottery_prize`;
CREATE TABLE IF NOT EXISTS `lottery_prize` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `prize_name` varchar(255) NOT NULL COMMENT '奖品名称',
  `description` text COMMENT '奖品描述',
  `prize_level` tinyint(1) NOT NULL DEFAULT '1' COMMENT '奖品等级1-8',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=启用，0=禁用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='抽奖奖品表';

